import { MakeLogicType, actions, connect, kea, listeners, path, selectors } from 'kea'

import { FeatureFlagsSet, featureFlagLogic } from 'lib/logic/featureFlagLogic'

import { osBridgeLogic } from '../bridge/osBridgeLogic'
import { osDockLogic } from '../dock/osDockLogic'
import { OS_SYSTEM_APPS, OsApp } from '../store/osAppCatalog'
import { osInstalledAppsLogic } from '../store/osInstalledAppsLogic'
import { OsWindowState, osWindowsLogic } from '../windows/osWindowsLogic'
import { OsAppMenu, osAppMenuFor } from './osAppMenus'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface osMenuBarLogicValues {
    featureFlags: FeatureFlagsSet // featureFlagLogic
    windowAppKeys: Record<string, string> // osDockLogic
    catalogApps: OsApp[] // osInstalledAppsLogic
    focusedWindow: OsWindowState | null // osWindowsLogic
    appMenu: OsAppMenu | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface osMenuBarLogicActions {
    navigateWindow: (
        windowId: string,
        path: string
    ) => {
        path: string
        windowId: string
    } // osBridgeLogic
    openWindow: (
        path: string,
        options?: import('../windows/osWindowsLogic').OsOpenWindowOptions | undefined
    ) => {
        id: string
        options: import('../windows/osWindowsLogic').OsOpenWindowOptions
        path: string
    } // osWindowsLogic
    openAppPage: (href: string) => {
        href: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface osMenuBarLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        appMenu: (
            focusedWindow: OsWindowState | null,
            catalogApps: OsApp[],
            featureFlags: FeatureFlagsSet,
            windowAppKeys: any
        ) => OsAppMenu | null
    }
}

export type osMenuBarLogicType = MakeLogicType<
    osMenuBarLogicValues,
    osMenuBarLogicActions,
    Record<string, any>,
    osMenuBarLogicMeta
>

/** The menu bar's app menu: the pages of the app in the focused window. */
export const osMenuBarLogic = kea<osMenuBarLogicType>([
    path(['scenes', 'os', 'shell', 'osMenuBarLogic']),
    connect(() => ({
        values: [
            osWindowsLogic,
            ['focusedWindow'],
            osInstalledAppsLogic,
            ['catalogApps'],
            featureFlagLogic,
            ['featureFlags'],
            osDockLogic,
            ['windowAppKeys'],
        ],
        actions: [osBridgeLogic, ['navigateWindow'], osWindowsLogic, ['openWindow']],
    })),
    actions({
        openAppPage: (href: string) => ({ href }),
    }),
    selectors({
        appMenu: [
            (s) => [s.focusedWindow, s.catalogApps, s.featureFlags, s.windowAppKeys],
            (
                focusedWindow: OsWindowState | null,
                catalogApps: OsApp[],
                featureFlags: FeatureFlagsSet,
                windowAppKeys: Record<string, string>
            ): OsAppMenu | null =>
                osAppMenuFor(
                    focusedWindow?.path ?? null,
                    [...OS_SYSTEM_APPS, ...catalogApps],
                    featureFlags,
                    focusedWindow ? windowAppKeys[focusedWindow.id] : undefined
                ),
        ],
    }),
    listeners(({ actions, values }) => ({
        openAppPage: ({ href }) => {
            const target = values.focusedWindow
            if (target) {
                actions.navigateWindow(target.id, href)
            } else {
                actions.openWindow(href)
            }
        },
    })),
])
